import { describe, expect, it } from 'vitest';
import * as fs from 'node:fs';
import * as path from 'node:path';
import { compileGoal, decideGoal, decidePolicy, decodeGoal, encodeGoal, liftLegacy, refDecide, renderCard, renderTape, typecheck, type Act, type Goal, type Hist } from '../src';
import { CNT, EUR, ONT, Rng, USD, baseGoal, ctrue, lteAmt, randAct, randGoal, randHist, usd } from './fixtures';

// The proved compiler is generated by formal/dafny/build-ext.sh Goal. CI sets PCA_GOAL_REQUIRE=1 (a missing file is a FAILURE there);
// a tree without it skips only the tests that need the extracted code, never silently in CI.
const haveGen = fs.existsSync(path.resolve(__dirname, '../../pca-verified-core/generated/pca_goal.js'));
if (process.env.PCA_GOAL_REQUIRE === '1' && !haveGen) throw new Error('generated/pca_goal.js is missing but PCA_GOAL_REQUIRE=1');
const proved = haveGen ? describe : describe.skip;
const empty: Hist = { adms: [], last: -1, aggs: {} };
const act = (o: Partial<Act> = {}): Act => ({ verb: 'pay.refund', res: 'ch_1', params: { amount: { k: 'q', q: usd(1000) } }, t: 10, sess: 's1', prin: 'P1', org: 'O', agent: 'a1', depth: 0, ...o });
const D = (g: Goal, a: Act, h: Hist = empty) => decideGoal(g, ONT, a, h);

describe('codec (no extracted code needed)', () => {
  it('encodeGoal/decodeGoal round-trips random goals, including holes', () => {
    const r = new Rng(7);
    for (let i = 0; i < 300; i++) {
      const g = randGoal(r);
      if (i % 5 === 0) g.holes = [{ hid: 'h1', q: 'which "customer"?', domain: ['a', 'b'], affects: ['g1'], global: i % 2 === 0 }];
      expect(decodeGoal(encodeGoal(g))).toStrictEqual(g);
    }
  });
  it('all_of: round-trips, and the reference semantics admits exactly the resources every part admits', () => {
    const g = baseGoal({ grants: [{ gid: 'g1', verb: 'pay.refund', res: { k: 'all_of', parts: [{ k: 'related', rel: 'charges_of', anchor: 'C1' }, { k: 'oneof', ids: ['ch_1', 'ch_9'] }] }, cond: ctrue }], wildcardAck: [], deleg: { maxDepth: 0, narrowOnly: true, mayTouch: [] } });
    expect(decodeGoal(encodeGoal(g))).toStrictEqual(g);
    const d = (res: string) => refDecide(g, ONT, act({ res }), empty);
    expect([d('ch_1'), d('ch_2'), d('ch_9')]).toStrictEqual([2, 0, 0]); // ch_2 is only in the relation, ch_9 only in the list
    expect(renderCard(g).lines.join('\n')).toMatch(/ALL OF/);
  });
  it('refuses non-integers and unknown discriminants', () => {
    expect(() => encodeGoal(baseGoal({ validity: { notBefore: 0.5, notAfter: 1, maxIdle: 0 } }))).toThrow(/safe integer/);
    expect(() => encodeGoal({ ...baseGoal(), grants: [{ gid: 'g', verb: 'v', res: { k: 'bogus' } as never, cond: ctrue }] })).toThrow(/unknown resource/);
  });
  it('the card prints every field: two different goals never print the same card', () => {
    const base = baseGoal();
    const variants: Goal[] = [
      { ...base, v: 2 }, { ...base, principal: 'P2' }, { ...base, nlDigest: 'x' }, { ...base, sources: ['s'] },
      { ...base, validity: { ...base.validity, notAfter: 5 } }, { ...base, deleg: { ...base.deleg, maxDepth: 3 } },
      { ...base, grants: [{ ...base.grants[0]!, cond: lteAmt(5001) }, ...base.grants.slice(1)] },
      { ...base, bounds: [{ bid: 'b', sel: { k: 'gids', gids: ['g1'] }, agg: 'count', value: { k: 'lit', v: { k: 'q', q: { u: CNT, n: 1 } } }, key: '', window: { k: 'lifetime' }, scope: { k: 'session' }, cap: { u: CNT, n: 3 }, onExceed: 'deny' }] },
    ];
    const seen = new Set([renderCard(base).lines.join('\n')]);
    for (const v of variants) expect(seen.add(renderCard(v).lines.join('\n')).size).toBe(seen.size);
    expect(renderCard(base).warnings.join()).toMatch(/every resource/);
  });
});

proved('proved compiler (extracted Dafny)', () => {
  it('G-T10: renderTape is lossless on random goals', () => {
    const r = new Rng(11);
    for (let i = 0; i < 200; i++) { const g = randGoal(r); expect(decodeGoal(renderTape(g))).toStrictEqual(g); }
  });

  it('G-T1: compiled decision == reference semantics == independent TS semantics; every Allow has a checked witness (G-T3)', () => {
    const r = new Rng(21);
    let allows = 0, typed = 0;
    for (let i = 0; i < 400; i++) {
      const g = randGoal(r);
      if (typecheck(g, ONT).length > 0) { expect(compileGoal(g, ONT).ok).toBe(false); continue; }
      typed++;
      for (let j = 0; j < 8; j++) {
        const a = randAct(r), h = randHist(r, g);
        const ref = D(g, a, h);
        const p = decidePolicy(g, ONT, a, h);
        if (!p.ok) throw new Error('well-typed goal did not compile');
        expect(p.decision).toBe(ref);
        expect(['deny', 'escalate', 'allow'][refDecide(g, ONT, a, h)]).toBe(ref);
        if (ref === 'allow') { allows++; expect(p.witness && g.grants.some((x) => x.gid === p.witness!.gid)).toBeTruthy(); expect(p.witnessChecked).toBe(true); }
        else expect(p.witness).toBeNull();
      }
    }
    expect(typed).toBeGreaterThan(100);
    expect(allows).toBeGreaterThan(50);
  });

  it('G-T2: adding a constraint never grows the allow set (random)', () => {
    const r = new Rng(33);
    const rank = { deny: 0, escalate: 1, allow: 2 } as const;
    let checked = 0;
    for (let i = 0; i < 300; i++) {
      const g = randGoal(r);
      if (typecheck(g, ONT).length) continue;
      const k = r.int(4);
      const g2: Goal = k === 0 ? { ...g, prohibits: [...g.prohibits, { pid: 'p9', target: { k: 'verb' as const, verb: r.pick(['pay.refund', 'pay.read', 'pay.transfer']) }, res: { k: 'any' as const, reason: 'r' }, cond: ctrue }].sort((a, b) => (a.pid < b.pid ? -1 : 1)) }
        : k === 1 ? { ...g, escalateOn: [...g.escalateOn, ctrue] }
        : k === 2 ? { ...g, validity: { ...g.validity, notAfter: g.validity.notAfter - r.int(900_000) } }
        : { ...g, grants: g.grants.map((x) => ({ ...x, cond: { k: 'and', a: x.cond, b: lteAmt(r.int(8) * 1000) } as const })) };
      if (typecheck(g2, ONT).length) continue;
      for (let j = 0; j < 10; j++) {
        const a = randAct(r), h = randHist(r, g);
        expect(rank[D(g2, a, h)]).toBeLessThanOrEqual(rank[D(g, a, h)]);
        checked++;
      }
    }
    expect(checked).toBeGreaterThan(500);
  });

  it('G-T7: a goal with holes compiles to a policy no wider than the completed goal; it is never signable', () => {
    const g = baseGoal({ holes: [{ hid: 'h1', q: 'all charges or one?', domain: ['one', 'all'], affects: ['g1'], global: false }] });
    expect(typecheck(g, ONT)).toEqual([]);
    const p = decidePolicy(g, ONT, act(), empty);
    expect(p.ok && p.decision).toBe('deny'); // the grant that depends on the hole is dropped
    expect(D({ ...g, holes: [] }, act())).toBe('allow');
  });

  it('G-T6: mixed currencies and untyped comparisons are rejected, not coerced', () => {
    const eur: Goal = baseGoal({ grants: [{ gid: 'g1', verb: 'pay.refund', res: { k: 'exact', id: 'x' }, cond: { k: 'cmp', op: 'lte', l: { k: 'param', path: 'amount', ty: { k: 'q', u: USD } }, r: { k: 'lit', v: { k: 'q', q: { u: EUR, n: 5 } } } } }], wildcardAck: [] });
    expect(typecheck(eur, ONT)).toContain('ill_typed_grant');
    const undeclared = baseGoal({ grants: [{ gid: 'g1', verb: 'pay.wire', res: { k: 'exact', id: 'x' }, cond: ctrue }], wildcardAck: [] });
    expect(typecheck(undeclared, ONT)).toContain('ill_typed_grant'); // closed world
    const wrongParam = baseGoal({ grants: [{ gid: 'g1', verb: 'pay.refund', res: { k: 'exact', id: 'x' }, cond: { k: 'cmp', op: 'lte', l: { k: 'param', path: 'amount', ty: { k: 's' } }, r: { k: 'lit', v: { k: 's', s: 'a' } } } }], wildcardAck: [] });
    expect(typecheck(wrongParam, ONT).length).toBeGreaterThan(0);
  });

  it('typing: wildcard needs acknowledgement; clause order must be canonical; ordering on text is ill-typed', () => {
    expect(typecheck(baseGoal({ wildcardAck: [] }), ONT)).toContain('ill_typed_grant');
    const g = baseGoal();
    expect(typecheck({ ...g, grants: [g.grants[1]!, g.grants[0]!] }, ONT)).toContain('not_canonical_order');
    const textLt = baseGoal({ grants: [{ gid: 'g1', verb: 'mail.send', res: { k: 'exact', id: 'x' }, cond: { k: 'cmp', op: 'lt', l: { k: 'param', path: 'to', ty: { k: 's' } }, r: { k: 'lit', v: { k: 's', s: 'z' } } } }], wildcardAck: [] });
    expect(typecheck(textLt, ONT).length).toBeGreaterThan(0);
  });

  it('W13: a prohibition by effect class covers every verb of the class (aliasing does not bypass it)', () => {
    const g = baseGoal({ prohibits: [{ pid: 'p1', target: { k: 'effect', cls: 'money_out' }, res: { k: 'any', reason: 'r' }, cond: ctrue }] });
    expect(D(g, act())).toBe('deny');
    expect(D(g, act({ verb: 'pay.transfer' }))).toBe('deny');
    expect(D(g, act({ verb: 'pay.read' }))).toBe('allow');
  });

  it('G-T4: Unknown never yields Allow: a missing parameter escalates', () => {
    expect(D(baseGoal(), act({ params: {} }))).toBe('escalate');
    expect(D(baseGoal({ escalateOn: [ctrue] }), act())).toBe('escalate');
  });

  it('G-T5: equal goals give byte-identical policies', () => {
    const a = compileGoal(baseGoal(), ONT), b = compileGoal(decodeGoal(encodeGoal(baseGoal())), ONT);
    expect(JSON.stringify(a)).toBe(JSON.stringify(b));
  });

  it('mutation sensitivity: the probe corpus tells apart every one-step mutant of the goal', () => {
    const r = new Rng(55);
    const fb = baseGoal();
    // closed world: a prohibit on a verb no grant names changes nothing, so the probed verb needs a grant for the prohibit to matter
    const base = baseGoal({
      grants: [...fb.grants, { gid: 'g3', verb: 'pay.transfer', res: { k: 'oneof', ids: ['ch_1'] }, cond: ctrue }],
      prohibits: [{ pid: 'p1', target: { k: 'verb', verb: 'pay.transfer' }, res: { k: 'any', reason: 'r' }, cond: ctrue }],
      bounds: [{ bid: 'b1', sel: { k: 'gids', gids: ['g1'] }, agg: 'sum', value: { k: 'param', path: 'amount', ty: { k: 'q', u: USD } }, key: '', window: { k: 'sliding', ms: 1000 }, scope: { k: 'session' }, cap: usd(8000), onExceed: 'deny' }],
      escalateOn: [{ k: 'cmp', op: 'gt', l: { k: 'param', path: 'amount', ty: { k: 'q', u: USD } }, r: { k: 'lit', v: { k: 'q', q: usd(4000) } } }],
    });
    const mutants: Record<string, Goal> = {
      dropProhibit: { ...base, prohibits: [] },
      dropBound: { ...base, bounds: [] },
      capUp: { ...base, bounds: [{ ...base.bounds[0]!, cap: usd(8001) }] },
      capDown: { ...base, bounds: [{ ...base.bounds[0]!, cap: usd(7999) }] },
      windowWider: { ...base, bounds: [{ ...base.bounds[0]!, window: { k: 'sliding', ms: 1001 } }] },
      windowTighter: { ...base, bounds: [{ ...base.bounds[0]!, window: { k: 'sliding', ms: 999 } }] },
      onExceed: { ...base, bounds: [{ ...base.bounds[0]!, onExceed: 'escalate' }] },
      dropEscalate: { ...base, escalateOn: [] },
      condUp: { ...base, grants: [{ ...base.grants[0]!, cond: lteAmt(5001) }, ...base.grants.slice(1)] },
      condDown: { ...base, grants: [{ ...base.grants[0]!, cond: lteAmt(4999) }, ...base.grants.slice(1)] },
      validityUp: { ...base, validity: { ...base.validity, notAfter: base.validity.notAfter + 1 } },
      depthUp: { ...base, deleg: { ...base.deleg, maxDepth: 3 } },
      dropMayTouch: { ...base, deleg: { ...base.deleg, mayTouch: [] } },
      resWider: { ...base, grants: [{ ...base.grants[0]!, res: { k: 'any', reason: 'r' } }, ...base.grants.slice(1)], wildcardAck: ['g1', 'g2'] },
    };
    const probes: [Act, Hist][] = [];
    for (const n of [2999, 3000, 3001, 4000, 4001, 4999, 5000, 5001]) {
      probes.push([act({ params: { amount: { k: 'q', q: usd(n) } } }), empty]);
      // the cap (8000) sits above the condition's ceiling (5000), so neither masks the other: the earlier admission of 3001 decides it
      for (const dt of [10, 999, 1000, 1001]) probes.push([act({ t: 2000, params: { amount: { k: 'q', q: usd(n) } } }), { adms: [{ gid: 'g1', act: act({ t: 2000 - dt, params: { amount: { k: 'q', q: usd(3001) } } }) }], last: 2000 - dt, aggs: {} }]);
    }
    probes.push([act({ t: 1_000_000 }), empty], [act({ t: 1_000_001 }), empty], [act({ depth: 3, t: 5 }), empty], [act({ depth: 1 }), empty], [act({ verb: 'pay.transfer' }), empty], [act({ res: 'zz' }), empty]);
    for (let i = 0; i < 100; i++) probes.push([randAct(r), empty]);
    const baseOut = probes.map(([a, h]) => D(base, a, h));
    for (const [name, m] of Object.entries(mutants)) {
      expect(typecheck(m, ONT), name).toEqual([]);
      expect(probes.map(([a, h]) => D(m, a, h)), `mutant ${name} survives`).not.toEqual(baseOut);
    }
  });

  describe('liftLegacy: the facade bugs, fixed through the compiler', () => {
    const lift = (permissions: Record<string, string[]>, limits: Record<string, string>) => liftLegacy({ permissions, limits, principal: 'P1' });
    const dec = (l: ReturnType<typeof lift>, a: Act, h: Hist = empty) => decideGoal(l.goal, l.ontology, a, h);
    const refund = (cents: number, t: number): Act => act({ verb: 'stripe.refund', res: '*', t, params: { amount: { k: 'q', q: usd(cents) } } });

    it('W5: $200/day is a sliding 24 h cap: two $150 refunds in a day are not both allowed, but the next day is', () => {
      const l = lift({ stripe: ['refund'] }, { refund: '$200/day' });
      expect(typecheck(l.goal, l.ontology)).toEqual([]);
      const first = refund(15000, 1000);
      expect(dec(l, first)).toBe('allow');
      const h: Hist = { adms: [{ gid: 'g:stripe.refund', act: first }], last: 1000, aggs: {} };
      expect(dec(l, refund(15000, 2000), h)).toBe('deny');
      expect(dec(l, refund(5000, 2000), h)).toBe('allow');
      expect(dec(l, refund(15000, 1000 + 86_400_000 + 1), h)).toBe('allow'); // the grant renews: the old facade expired for good
    });
    it('W6: a $ limit on a verb without an amount field is an error', () => {
      expect(() => lift({ stripe: ['create_customer'] }, { create_customer: '$10' })).toThrow(/amount field/);
    });
    it('W7a: a second count limit narrows, never widens', () => {
      const one = lift({ gmail: ['send'] }, { send: '1/hour' });
      const two = lift({ gmail: ['send'], slack: ['post_message'] }, { send: '1/hour', post_message: '9/hour' });
      const a = act({ verb: 'gmail.send', res: '*', params: {}, t: 100 });
      const h: Hist = { adms: [{ gid: 'g:gmail.send', act: { ...a, t: 50 } }], last: 50, aggs: {} };
      expect(dec(one, a, h)).toBe('deny');
      expect(decideGoal(two.goal, two.ontology, a, h)).toBe('deny'); // the first limit is still there
    });
    it('W7b: co-sign tiers are not part of the goal, so a $ limit cannot remove them; a per-call $ cap still holds', () => {
      const l = lift({ stripe: ['payout'] }, { payout: '$50' });
      expect(dec(l, act({ verb: 'stripe.payout', res: '*', params: { amount: { k: 'q', q: usd(5000) } } }))).toBe('allow');
      expect(dec(l, act({ verb: 'stripe.payout', res: '*', params: { amount: { k: 'q', q: usd(5001) } } }))).toBe('deny');
      expect(dec(l, act({ verb: 'stripe.payout', res: '*', params: { amount: { k: 'q', q: { u: EUR, n: 1 } } } }))).toBe('escalate'); // EUR is not USD: no coercion
    });
  });
});
